import{_ as o,o as t,c as a,a8 as r}from"./chunks/framework.On_KnKH5.js";const g=JSON.parse('{"title":"CI/CD and workflow behavior","description":"","frontmatter":{},"headers":[],"relativePath":"ci-cd.md","filePath":"ci-cd.md"}'),s={name:"ci-cd.md"};function n(i,e,l,c,d,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="ci-cd-and-workflow-behavior" tabindex="-1">CI/CD and workflow behavior <a class="header-anchor" href="#ci-cd-and-workflow-behavior" aria-label="Permalink to “CI/CD and workflow behavior”">​</a></h1><p>All workflows live under <a href="https://github.com/bcgov/bcew-monorepo/tree/main/.github/workflows" target="_blank" rel="noreferrer"><code>.github/workflows/</code></a>. This page summarizes behavior; inline workflow comments and the <a href="https://github.com/bcgov/bcew-monorepo/blob/main/.github/workflows/README.md" target="_blank" rel="noreferrer">workflows README</a> are authoritative for details.</p><h2 id="pull-requests-pr-yml" tabindex="-1">Pull requests (<code>pr.yml</code>) <a class="header-anchor" href="#pull-requests-pr-yml" aria-label="Permalink to “Pull requests (pr.yml)”">​</a></h2><p><strong>Triggers:</strong> Every <code>pull_request</code> event.</p><p><strong>Concurrency:</strong> One run per PR; newer commits cancel in-progress runs for that PR.</p><p><strong>Typical steps:</strong></p><ol><li><strong>Labeler</strong> — Applies labels from <code>.github/labeler.yml</code> based on changed paths.</li><li><strong>Install</strong> — pnpm and Node (see workflow for versions), <code>pnpm install</code>, root <code>composer install</code>.</li><li><strong>Lint</strong> — Full monorepo lint: PHP, JS, CSS, Markdown, <code>package.json</code>.</li><li><strong>Build</strong> — <code>npx nx affected --base=&quot;origin/&lt;base_branch&gt;&quot; -t build</code> so only <strong>affected</strong> projects build.</li><li><strong>Tests</strong>: <ol><li><strong>Integration</strong> — PHP WordPress integration tests using wp-env.</li><li><strong>e2e</strong> — e2e tests using Playwright and wp-env.</li><li><strong>Screenshot</strong> — Visual regression tests using Playwright and wp-env. Compares screenshots <ul><li><strong>Note</strong>: If a screenshot test fails in the CI/CD, check the artifact it uploads during the <code>actions/upload-artifact</code> step. It will contain a zip of the diff between the expected screenshots and the ones it produced. Usually the fix for this will require running <code>npx nx test-screenshot-generate</code> locally to generate new screenshots.</li></ul></li></ol></li><li><strong>Artifacts</strong> — Playwright report uploaded on completion (unless cancelled).</li></ol><h3 id="how-affected-is-chosen" tabindex="-1">How “affected” is chosen <a class="header-anchor" href="#how-affected-is-chosen" aria-label="Permalink to “How “affected” is chosen”">​</a></h3><p>The PR workflow compares the PR head to <code>origin/&lt;github.base_ref&gt;</code> (the target branch, usually <code>main</code>). Any project touched or implied by the Nx graph runs the expensive targets.</p><h2 id="merges-to-main" tabindex="-1">Merges to <code>main</code> <a class="header-anchor" href="#merges-to-main" aria-label="Permalink to “Merges to main”">​</a></h2><ul><li><strong>Docs:</strong> Pushes to <code>main</code> that touch <code>docs/**</code>, package <code>docs/**</code>, sync script, or docs workflow deploy the VitePress site via <code>deploy-docs.yml</code> (see <a href="./documentation-site">Documentation site</a>).</li><li><strong>Releases:</strong> Merging code does <strong>not</strong> by itself publish plugin/theme zip artifacts. A maintainer starts <strong><code>tag.yml</code></strong> from Actions. That workflow creates the tag.</li></ul><h2 id="tags-tag-yml" tabindex="-1">Tags (<code>tag.yml</code>) <a class="header-anchor" href="#tags-tag-yml" aria-label="Permalink to “Tags (tag.yml)”">​</a></h2><p>On the GitHub repository, navigate to Actions &gt; Release Subproject and Update packages.json &gt; Run workflow.</p><p>You do not type a version. The workflow reads existing <code>{project}/v*</code> tags and picks the next one.</p><p>Inputs:</p><ul><li><strong>Use workflow from:</strong> the branch to release. A release from a branch other than <code>main</code> should stay an alpha. Most releases run from <code>main</code>.</li><li><strong>Project to release:</strong> dropdown of monorepo projects. This list is <strong>hardcoded</strong> in <code>tag.yml</code> (<code>workflow_dispatch.inputs.name.options</code>). When you <a href="./renaming-projects">rename a project</a>, add the new Nx name here or you cannot cut a release.</li><li><strong>Alpha:</strong> ticked by default. Leave it ticked for an alpha. Untick it for a real release.</li></ul><p>How the next version is chosen:</p><ul><li>A project with no <code>{project}/v*</code> tags starts at <code>1.0.0-alpha.1</code> (or <code>1.0.0</code> if Alpha is unticked).</li><li>Alphas count up on the same <code>X.Y.Z</code> (<code>1.0.0-alpha.1</code>, then <code>1.0.0-alpha.2</code>).</li><li>Unticking Alpha ships that <code>X.Y.Z</code> when it is not tagged yet.</li><li>After a real release, the next series is the next minor (<code>1.0.0</code> → <code>1.1.0</code> or <code>1.1.0-alpha.1</code>). Patch and major are not bumped.</li><li>Tags that are not <code>X.Y.Z</code> or <code>X.Y.Z-alpha.N</code> (for example <code>1.1.0-a1</code>) are ignored.</li></ul><p>What this workflow does:</p><ol><li>Nx Release writes that version into the project&#39;s <code>package.json</code> and <code>CHANGELOG.md</code>, commits those files, and tags <code>{project}/v{version}</code> (for example <code>bcew-blocks/v1.0.0-alpha.1</code>).</li><li>Plugin PHP files and theme <code>style.css</code> in git are not edited.</li><li>Builds the project and creates a zip named <code>&lt;project&gt;-&lt;version&gt;.zip</code> (for example <code>bcew-blocks-1.0.0-alpha.1.zip</code>). The zip&#39;s <code>Version:</code> header is set to that version, including alphas.</li><li>Creates a GitHub Release from the changelog and attaches the zip. An alpha version is published as a prerelease.</li><li>Updates <code>packages.json</code> for the Composer repository on GitHub Pages and deploys it.</li></ol>',20)])])}const u=o(s,[["render",n]]);export{g as __pageData,u as default};
